#!/usr/bin/env python3import cv2from datetime import datetime  # Import datetime module# Open video capturecap = cv2.VideoCapture(15)# Check if the camera is opened successfullyif not cap.isOpened():    print("Error: Could not open the camera.")    exit()# Set camera resolution cap.set(cv2.CAP_PROP_FRAME_WIDTH, 1280)cap.set(cv2.CAP_PROP_FRAME_HEIGHT, 720)while True:    success, img = cap.read()    if not success:        break    img = cv2.flip(img, 1)  # Flip image horizontally    cv2.imshow('camera', img)    # Check for key press    key = cv2.waitKey(1) & 0xFF    if key == ord('s'):  # Press 's' to save the image        timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')  # Generate timestamp        filename = f'/home/pi/ros_catkin_ws/src/dual_rosserial/scripts/pictures_camera/newimage_{timestamp}.jpg'  # Create unique filename        cv2.imwrite(filename, img)        print(f"Picture saved to {filename}")    elif key == ord('q'):  # Press 'q' to quit        breakcap.release()cv2.destroyAllWindows()